// ── COZY EDINBURGH EVENING — warm pub interior ──

svg += `<defs>
  <linearGradient id="lg-cee" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0A0A0E' : '#2A2420'}"/>
    <stop offset="100%" stop-color="${isN ? '#141418' : '#3A3228'}"/>
  </linearGradient>
  <linearGradient id="lg-cee-wall" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#5A4A3A"/>
    <stop offset="100%" stop-color="#4A3A2A"/>
  </linearGradient>
  <linearGradient id="lg-cee-window" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#1A2A40' : '#4A6A8A'}"/>
    <stop offset="60%" stop-color="${isN ? '#2A3A50' : '#5A8AAA'}"/>
    <stop offset="100%" stop-color="${isN ? '#1A2838' : '#4A7090'}"/>
  </linearGradient>
  <radialGradient id="rg-cee-warm">
    <stop offset="0%" stop-color="rgba(224,138,48,0.12)"/>
    <stop offset="100%" stop-color="rgba(224,138,48,0)"/>
  </radialGradient>
</defs>`;
// Interior background (warm, dark)
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-cee)"/>`;

// ── Warm ambient light glow ──
svg += `<circle cx="${w * 0.5}" cy="${h * 0.3}" r="${w * 0.4}" fill="url(#rg-cee-warm)"/>`;
svg += `<circle cx="${w * 0.2}" cy="${h * 0.5}" r="${w * 0.25}" fill="rgba(224,138,48,0.03)"/>`;

// ═══ BACK WALL (brick) ═══
const wallY = h * 0.35;
svg += `<rect x="0" y="${wallY}" width="${w}" height="${h * 0.25}" fill="url(#lg-cee-wall)"/>`;
// Brick pattern
for (let row = 0; row < 6; row++) {
  const by2 = wallY + row * (h * 0.04);
  const offset = row % 2 === 0 ? 0 : w * 0.04;
  for (let col = 0; col < 14; col++) {
    const bx = offset + col * (w * 0.08);
    const bShade = 0.02 + Math.sin(row * 3.1 + col * 1.7) * 0.02;
    svg += `<rect x="${bx + 1}" y="${by2 + 1}" width="${w * 0.075}" height="${h * 0.035}" rx="1" fill="rgba(180,120,80,${bShade})" stroke="rgba(90,70,50,0.15)" stroke-width="0.5"/>`;
  }
}

// ═══ LARGE WINDOW (right side, showing blue evening sky) ═══
const winX = w * 0.55;
const winY = h * 0.05;
const winW2 = w * 0.4;
const winH2 = h * 0.45;
// Window frame
svg += `<rect x="${winX}" y="${winY}" width="${winW2}" height="${winH2}" rx="2" fill="url(#lg-cee-window)" stroke="#3A3228" stroke-width="${ol * 0.8}"/>`;
// Window panes (cross mullion)
svg += `<line x1="${winX + winW2 / 2}" y1="${winY}" x2="${winX + winW2 / 2}" y2="${winY + winH2}" stroke="#3A3228" stroke-width="${ol * 0.6}"/>`;
svg += `<line x1="${winX}" y1="${winY + winH2 * 0.45}" x2="${winX + winW2}" y2="${winY + winH2 * 0.45}" stroke="#3A3228" stroke-width="${ol * 0.6}"/>`;
// Reflections on glass
for (let i = 0; i < 3; i++) {
  const rfx = winX + winW2 * 0.15 + i * winW2 * 0.3;
  const rfy = winY + winH2 * 0.1 + i * winH2 * 0.2;
  svg += `<line x1="${rfx}" y1="${rfy}" x2="${rfx + 8}" y2="${rfy + 15}" stroke="rgba(200,220,240,0.08)" stroke-width="2" stroke-linecap="round"/>`;
}
// Outside: faint buildings/street visible
svg += `<rect x="${winX + winW2 * 0.6}" y="${winY + winH2 * 0.3}" width="8" height="${winH2 * 0.15}" fill="rgba(100,100,90,0.15)"/>`;
svg += `<rect x="${winX + winW2 * 0.75}" y="${winY + winH2 * 0.25}" width="6" height="${winH2 * 0.2}" fill="rgba(100,100,90,0.12)"/>`;

// ── Hanging plants from top of window ──
for (let i = 0; i < 3; i++) {
  const hpx = winX + winW2 * 0.2 + i * winW2 * 0.3;
  const hpy = winY + 3;
  // Trailing vine
  for (let v = 0; v < 6; v++) {
    const vx = hpx + Math.sin(mt * 0.5 + i * 1.3 + v * 0.8) * 4;
    const vy = hpy + v * 6;
    svg += `<circle cx="${vx}" cy="${vy}" r="2.5" fill="#3A7A3A" opacity="${0.5 - v * 0.06}"/>`;
    if (v < 5) svg += `<line x1="${vx}" y1="${vy + 2}" x2="${hpx + Math.sin(mt * 0.5 + i * 1.3 + (v + 1) * 0.8) * 4}" y2="${hpy + (v + 1) * 6 - 2}" stroke="#2A5A2A" stroke-width="0.8" opacity="0.4"/>`;
  }
}

// ═══ FLOOR (concrete/stone) ═══
svg += `<rect x="0" y="${h * 0.6}" width="${w}" height="${h * 0.4}" fill="${sc.ground}"/>`;
// Floor texture
for (let i = 0; i < 8; i++) {
  const flx = i * (w / 8);
  svg += `<line x1="${flx}" y1="${h * 0.6}" x2="${flx + w * 0.06}" y2="${h}" stroke="#4A4238" stroke-width="0.5" opacity="0.2"/>`;
}

// ═══ LEATHER ARMCHAIR (center-left, riveted) ═══
const chX = w * 0.25;
const chY = h * 0.55;
const chW2 = w * 0.22;
const chH2 = h * 0.35;

// Chair back
svg += `<rect x="${chX - chW2 / 2}" y="${chY - chH2 * 0.6}" width="${chW2}" height="${chH2 * 0.6}" rx="4" fill="#5A3A28" stroke="#3A2818" stroke-width="${ol}"/>`;
// Chair arm (right side, visible)
svg += `<rect x="${chX + chW2 / 2 - 8}" y="${chY - chH2 * 0.45}" width="12" height="${chH2 * 0.55}" rx="3" fill="#5A3A28" stroke="#3A2818" stroke-width="${ol * 0.7}"/>`;
// Chair arm (left side)
svg += `<rect x="${chX - chW2 / 2 - 4}" y="${chY - chH2 * 0.45}" width="12" height="${chH2 * 0.55}" rx="3" fill="#4A2A18" stroke="#3A2818" stroke-width="${ol * 0.7}"/>`;
// Seat cushion
svg += `<rect x="${chX - chW2 / 2 + 5}" y="${chY - 5}" width="${chW2 - 10}" height="${chH2 * 0.25}" rx="3" fill="#5A3A28" stroke="#3A2818" stroke-width="${ol * 0.6}"/>`;
// Leather sheen highlights
svg += `<ellipse cx="${chX}" cy="${chY - chH2 * 0.3}" rx="${chW2 * 0.3}" ry="${chH2 * 0.15}" fill="rgba(180,140,100,0.08)"/>`;

// ── BRASS STUDS (rivets along the edges!) ──
// Right edge studs
for (let i = 0; i < 8; i++) {
  const sy = chY - chH2 * 0.55 + i * (chH2 * 0.55 / 7);
  const studGlow = Math.sin(mt * 1.5 + i * 0.7) * 0.1;
  svg += `<circle cx="${chX + chW2 / 2 + 3}" cy="${sy}" r="1.8" fill="#C8A060" stroke="#A08040" stroke-width="0.3" opacity="${0.7 + studGlow}"/>`;
  svg += `<circle cx="${chX + chW2 / 2 + 3}" cy="${sy}" r="0.6" fill="#E0C080" opacity="${0.5 + studGlow}"/>`;
}
// Left edge studs
for (let i = 0; i < 8; i++) {
  const sy = chY - chH2 * 0.55 + i * (chH2 * 0.55 / 7);
  svg += `<circle cx="${chX - chW2 / 2 + 5}" cy="${sy}" r="1.8" fill="#C8A060" stroke="#A08040" stroke-width="0.3" opacity="0.65"/>`;
}
// Top edge studs
for (let i = 0; i < 6; i++) {
  const sx = chX - chW2 / 2 + 8 + i * ((chW2 - 16) / 5);
  svg += `<circle cx="${sx}" cy="${chY - chH2 * 0.57}" r="1.8" fill="#C8A060" stroke="#A08040" stroke-width="0.3" opacity="0.7"/>`;
}
// Bottom edge studs
for (let i = 0; i < 5; i++) {
  const sx = chX - chW2 / 2 + 10 + i * ((chW2 - 20) / 4);
  svg += `<circle cx="${sx}" cy="${chY + chH2 * 0.18}" r="1.5" fill="#C8A060" opacity="0.55"/>`;
}

// ── ORANGE VELVET CUSHION (on the chair) ──
const cuX = chX - chW2 / 2 + 5;
const cuY = chY - chH2 * 0.35;
svg += `<rect x="${cuX}" y="${cuY}" width="${chW2 * 0.4}" height="${chH2 * 0.25}" rx="4" fill="#D07020" stroke="#B05A18" stroke-width="${ol * 0.4}" transform="rotate(-8 ${cuX + chW2 * 0.2} ${cuY + chH2 * 0.125})"/>`;
// Velvet texture shimmer
svg += `<ellipse cx="${cuX + chW2 * 0.2}" cy="${cuY + chH2 * 0.1}" rx="${chW2 * 0.12}" ry="${chH2 * 0.06}" fill="rgba(255,180,100,0.12)" transform="rotate(-8 ${cuX + chW2 * 0.2} ${cuY + chH2 * 0.1})"/>`;

// Chair legs (barely visible)
svg += `<line x1="${chX - chW2 / 2 + 5}" y1="${chY + chH2 * 0.2}" x2="${chX - chW2 / 2 + 3}" y2="${chY + chH2 * 0.3}" stroke="#3A2818" stroke-width="3" stroke-linecap="round"/>`;
svg += `<line x1="${chX + chW2 / 2 - 2}" y1="${chY + chH2 * 0.2}" x2="${chX + chW2 / 2}" y2="${chY + chH2 * 0.3}" stroke="#3A2818" stroke-width="3" stroke-linecap="round"/>`;

// ═══ STAGE / PLATFORM (background right) ═══
const stgX = w * 0.55;
const stgY = h * 0.55;
svg += `<rect x="${stgX}" y="${stgY}" width="${w * 0.45}" height="${h * 0.08}" fill="#3A3228" stroke="#2A2218" stroke-width="${ol * 0.4}"/>`;
// Stage skirt (black fabric)
svg += `<rect x="${stgX}" y="${stgY + h * 0.08}" width="${w * 0.45}" height="${h * 0.06}" fill="#1A1A1A" stroke="#0A0A0A" stroke-width="${ol * 0.2}"/>`;
// Curtain folds on skirt
for (let i = 0; i < 8; i++) {
  const cx2 = stgX + i * (w * 0.45 / 8);
  svg += `<line x1="${cx2}" y1="${stgY + h * 0.08}" x2="${cx2}" y2="${stgY + h * 0.14}" stroke="#2A2A2A" stroke-width="0.5" opacity="0.3"/>`;
}

// ── Microphone stand (left of stage) ──
const micX = w * 0.45;
svg += `<line x1="${micX}" y1="${h * 0.6}" x2="${micX}" y2="${h * 0.3}" stroke="#666" stroke-width="1.5"/>`;
svg += `<circle cx="${micX}" cy="${h * 0.28}" r="3" fill="#555" stroke="#444" stroke-width="0.5"/>`;
// Mic cable
svg += `<path d="M${micX} ${h * 0.31} Q${micX - 8} ${h * 0.45} ${micX - 5} ${h * 0.6}" fill="none" stroke="#444" stroke-width="1" opacity="0.4"/>`;

// ── Wooden shelf / windowsill with objects ──
const shY = wallY + h * 0.25;
svg += `<rect x="${w * 0.5}" y="${shY}" width="${w * 0.48}" height="4" fill="#6A5040" stroke="#5A4030" stroke-width="${ol * 0.3}"/>`;
// Small objects on shelf
// Plant pot
svg += `<rect x="${w * 0.6}" y="${shY - 8}" width="8" height="8" rx="1" fill="#8A6A4A" stroke="#6A4A2A" stroke-width="0.5"/>`;
svg += `<circle cx="${w * 0.604}" cy="${shY - 10}" r="5" fill="#3A7A3A" opacity="0.6"/>`;
svg += `<circle cx="${w * 0.608}" cy="${shY - 13}" r="4" fill="#4A8A4A" opacity="0.5"/>`;
// Small radio/speaker
svg += `<rect x="${w * 0.75}" y="${shY - 10}" width="10" height="10" rx="2" fill="#5A4A3A" stroke="#4A3A2A" stroke-width="0.5"/>`;
svg += `<circle cx="${w * 0.755}" cy="${shY - 5}" r="3" fill="#4A3A2A" stroke="#3A2A1A" stroke-width="0.3"/>`;

// ── Hanging curtain/drape (olive, left of window) ──
svg += `<rect x="${w * 0.5}" y="${h * 0.02}" width="${w * 0.06}" height="${h * 0.55}" rx="1" fill="#5A6A4A" opacity="0.6"/>`;
for (let i = 0; i < 5; i++) {
  const dfold = Math.sin(i * 1.5) * 2;
  svg += `<line x1="${w * 0.5 + 2 + dfold}" y1="${h * 0.05 + i * h * 0.1}" x2="${w * 0.5 + 2 + dfold}" y2="${h * 0.12 + i * h * 0.1}" stroke="#4A5A3A" stroke-width="0.5" opacity="0.3"/>`;
}

// ═══ WARM LIGHTING EFFECTS ═══
// Ceiling light (warm pendant)
const lightX = w * 0.35;
svg += `<line x1="${lightX}" y1="0" x2="${lightX}" y2="${h * 0.08}" stroke="#444" stroke-width="1"/>`;
svg += `<path d="M${lightX - 8} ${h * 0.08} Q${lightX} ${h * 0.12} ${lightX + 8} ${h * 0.08}" fill="#333" stroke="#444" stroke-width="0.5"/>`;
const bulbGlow = 0.6 + Math.sin(mt * 0.8) * 0.08;
svg += `<circle cx="${lightX}" cy="${h * 0.1}" r="3" fill="#FFD080" opacity="${bulbGlow}"/>`;
svg += `<circle cx="${lightX}" cy="${h * 0.1}" r="${40 + Math.sin(mt * 0.5) * 5}" fill="#FFD080" opacity="0.02"/>`;

// Second pendant light
const l2x = w * 0.7;
svg += `<line x1="${l2x}" y1="0" x2="${l2x}" y2="${h * 0.06}" stroke="#444" stroke-width="1"/>`;
svg += `<path d="M${l2x - 6} ${h * 0.06} Q${l2x} ${h * 0.09} ${l2x + 6} ${h * 0.06}" fill="#333" stroke="#444" stroke-width="0.5"/>`;
svg += `<circle cx="${l2x}" cy="${h * 0.08}" r="2.5" fill="#FFD080" opacity="${bulbGlow * 0.9}"/>`;
svg += `<circle cx="${l2x}" cy="${h * 0.08}" r="35" fill="#FFD080" opacity="0.015"/>`;

// ── Warm light puddle on floor from window ──
if (!isN) {
  svg += `<ellipse cx="${w * 0.6}" cy="${h * 0.7}" rx="${w * 0.12}" ry="${h * 0.08}" fill="rgba(160,180,200,0.04)"/>`;
}

// ── Wooden stool (near stage) ──
svg += `<rect x="${w * 0.48}" y="${h * 0.5}" width="8" height="3" rx="1" fill="#6A5040"/>`;
svg += `<line x1="${w * 0.48 + 1}" y1="${h * 0.53}" x2="${w * 0.48}" y2="${h * 0.6}" stroke="#5A4030" stroke-width="1.5"/>`;
svg += `<line x1="${w * 0.48 + 7}" y1="${h * 0.53}" x2="${w * 0.48 + 8}" y2="${h * 0.6}" stroke="#5A4030" stroke-width="1.5"/>`;

// ── Subtle dust motes floating in light beams ──
for (let i = 0; i < 8; i++) {
  const dmx = w * 0.2 + Math.sin(mt * 0.3 + i * 1.7) * w * 0.15;
  const dmy = h * 0.15 + Math.cos(mt * 0.2 + i * 1.1) * h * 0.2;
  const dmop = 0.08 + Math.sin(mt * 1.5 + i * 0.9) * 0.06;
  svg += `<circle cx="${dmx}" cy="${dmy}" r="${0.8 + Math.sin(i * 2.3) * 0.3}" fill="#FFE0A0" opacity="${dmop}"/>`;
}
